$csrf=static function()use($token,$e){echo '<input type="hidden" name="'.$e($token['name']).'" value="'.$e($token['hash']).'">';};
$input=static function($name,$label,$value='',$type='text',$extra='')use($e){echo '<label>'.$e($label).'<input name="'.$e($name).'" type="'.$e($type).'" value="'.$e($value).'" '.$extra.'></label>';};
$check=static function($name,$label,$value=false,$submitted='1')use($e){echo '<label class="setup-check-label"><input type="checkbox" name="'.$e($name).'" value="'.$e($submitted).'" '.($value?'checked':'').'><span>'.$e($label).'</span></label>';};
$select=static function($name,$label,$choices,$value='',$extra='')use($e){echo '<label>'.$e($label).'<select name="'.$e($name).'" '.$extra.'>';foreach($choices as$id=>$name)echo '<option value="'.$e($id).'" '.((string)$id===(string)$value?'selected':'').'>'.$e($name).'</option>';echo '</select></label>';};
$dest=static function($name,$label,$d=[])use($c,$admin,$select,$input){$select($name,$label,$admin->destinations($c),($d['type']??'None').':'.($d['number']??''),'data-destination');echo '<div data-external>';$input($name.'_external','External Number',$d['external']??'','tel');echo '</div>';};
$members=static function($selected)use($c,$access,$full,$check){$numbers=array_map('strval',array_column($selected,'number'));echo '<div class="admin-members">';foreach($c['users']as$n=>$u)if($access->permits('routing',(string)$n,$full,true))$check('members[]',$n.' · '.$u['name'],in_array((string)$n,$numbers,true),(string)$n);echo '</div>';};
$department=static fn($n)=>$n==='new'?['number'=>$_GET['department']??'']:(pbx_schedule::department($c,(string)$n)??['number'=>'']);
$readiness=$tab==='voice'?$admin->trunkReadiness():['trunks'=>[]];$trunkStatus=static fn($state)=>$e($state['status']);
$departmentName=static fn($name)=>in_array($name,['__DEFAULT','__DEFAULT__'],true)?'Default':$name;
$audioChoices=[''=>'None','keep-existing'=>'Keep Current Audio'];$audioIds=[];foreach($admin->media('prompts')as$audio){$audioChoices[$audio['media_uuid']]=$audio['title'];$audioIds[$audio['file_path']]=$audio['media_uuid'];}
$document['title']=$labels[$tab].' · My PBX';require PROJECT_ROOT.'/resources/header.php';
