 else{$suggestedExtension=$kind==='user'&&$key==='new'?$row['number']:'';$row['department']=$row['department']??($_GET['department']??''); ?>
 <form method="post" class="setup-form"><?php $csrf(); ?><input type="hidden" name="action" value="save"><?php require PROJECT_ROOT.'/app/pbx_setup/edit.php';$tab=$savedStaffTab; ?><button class="setup-button primary">Save</button></form><?php if($key!=='new'&&$kind!=='hours'&&$key!==$access->ownNumber()): ?><form method="post" class="setup-form"><?php $csrf(); ?><input type="hidden" name="action" value="delete"><?php $check('confirm_delete','I want to delete this item'); ?><button class="setup-button">Delete</button></form><?php endif; ?>
